`sidequest-metrics`:`sidequest.operation.duration`
| ifdef($environment_filter) { where environment == $environment_filter }
| ifdef($release_filter) { where `service.version` == $release_filter }
| ifdef($component_filter) { where component == $component_filter }
| ifdef($operation_filter) { where operation == $operation_filter }
| where operation == #/^http[.]/ and operation != "http.telemetry"
| bucket by operation to 5m using interpolate_delta_histogram(0.95)

